from gf import *
co=lambda y,t: f'<div class="coach" style="top:{y}px">{t}</div>'
hand=lambda x,y,ax=0: f'<div class="hand" style="left:{x}px;top:{y}px"></div>'+(f'<div class="arr" style="left:{x+36}px;top:{y+17}px;width:{ax}px"></div>' if ax else '')
E3='<span class="zt">字匣</span><div class="z em">空</div><div class="z em">空</div><div class="z em">空</div>'
t1=phone(pcard(who='第 1 张 · 族长',title='开春了',body='族长把骨刀交到你手里：「往后记事，就靠你了。」',rot=3,dx=20,opt=('接过骨刀',.4))+hand(220,420,60)+co(588,'左右拖卡做选择。拖过一小段再松手。'),dots=[0,8,0,0],tray=E3)
t2=phone(pcard(who='第 2 张 · 采集的妇人',title='她背回一筐野果',body='「分给大家，还是先存起来？」',scale=.98)+'<div style="position:absolute;left:12px;top:136px;width:336px;height:436px;border:2px solid #D8B46A;border-radius:20px"></div>'+co(588,'按住卡不放，看这一下会动哪几项。'),dots=[8,5,0,0],tray=E3)
t3=phone(pcard(who='第 3 张 · 巫',title='骨上有一道裂',body='「这道迹，刻下来能留给后人。」',extra='')+'<div style="position:absolute;right:20px;top:144px;width:52px;height:52px;border:2px solid #D8B46A;border-radius:12px"></div><div style="position:absolute;right:28px;top:152px;width:36px;height:36px;border-radius:9px 12px 8px 13px;background:linear-gradient(145deg,#F1E8D4,#E4D6B8);border:1.5px solid #B9A57C;font-family:Noto Serif CJK SC;font-weight:700;font-size:18px;color:#6E2F1F;display:flex;align-items:center;justify-content:center">刻</div>'+co(588,'点卡角的骨片，把这件事刻下来。'),tray=E3)
t4=phone(pcard(who='第 4 张 · 族长',title='河水漫过了界石',body='两家为一条河争了三天。',extra='<div style="position:absolute;left:16px;right:16px;bottom:16px;height:56px;border:2px dashed #D8B46A;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:13px;color:#766C5E">可落字：水</div>')+co(588,'族长借你一个「水」。点它，落在卡上。'),tray='<span class="zt">字匣</span><div class="z gl">水</div><div class="z em">空</div><div class="z em">空</div>')
t5=phone(pcard(who='第 5 张 · 外族来使',title='他们要一半的粮',body='给了，今冬难熬；不给，怕要动刀。',rot=-4,dx=-28,opt=('不给',.7))+co(588,'这次两边都有代价。想好再松手。'),dots=[12,0,0,12],tray='<span class="zt">字匣</span><div class="z em">已落</div><div class="z em">空</div><div class="z em">空</div>')
t6=phone('<div class="card" style="left:16px;top:140px;width:328px;height:428px;background:#1E2230;border:1px solid #D8B46A;color:#EEE7D8"><div class="h" style="color:#D8B46A">第 1 代结束 · 先人</div><div class="tt" style="color:#EEE7D8">「你记下的，会传下去。」</div><div class="b" style="color:#A8A193">你刻下的字进了字录。下一代记事人会从字录里挑三个字带上路。</div><div style="position:absolute;left:16px;right:16px;bottom:16px;height:44px;border-radius:22px;background:#B5432E;color:#fff;font-weight:700;display:flex;align-items:center;justify-content:center">交给第 2 代</div></div>',hudon=True,back=False,tray='<span class="zt">字录</span><div class="z">水</div><div class="z">休</div><span class="zt" style="width:auto">本代刻成</span>')
r1=''.join([col(t1,'<span style="color:#B5432E;font-weight:700">动效中间帧，越框是故意的</span><br><b>第 1 张 · 学滑卡</b>：只动一项；手势示意从卡中向右划，循环 2 次后停；拖过阈值一次即过关。'),col(t2,'<b>第 2 张 · 学看分量</b>：动两项；卡描金边，提示按住；按住 300ms 出圆点后提示消失。'),col(t3,'<b>第 3 张 · 学刻骨片</b>：带迹；卡角骨片描金框；点了才能继续（此卡左右拖锁定）。'),col(t4,'<b>第 4 张 · 学落字</b>：教学期借一个「水」进字匣；落下即过关。')])
r2=''.join([col(t5,'<span style="color:#B5432E;font-weight:700">动效中间帧，越框是故意的</span><br><b>第 5 张 · 学取舍</b>：两边各动两项、幅度最大；只给一句提醒，不再锁操作。'),col(t6,'<b>第 1 代结束 · 先人</b>：讲清「传给下一代」；按钮进入出发挑字（板 5）。'),'<div class="box" style="width:600px"><b>教学规则</b><br>· 前五张固定顺序，不洗牌；每张只教一件事，教会即收起提示。<br>· 提示条放在卡与字匣之间（top 588），不压卡面字；字号 13/20。<br>· 前三张不显示目标；第 1 代目标从第 6 张起亮出（板 4）。<br>· 第一次冬夜只给一张事签、一种造法（例：「休」人靠木），刻成后再告诉还有象形和指事。<br>· 是否给「跳过教学」入口：本稿不加，待用户定。<br>· 电脑端同流程，提示文案末尾加键位（如「或按 →」），只在宽屏显示。</div>'])
d1=desk(dcard(who='第 1 张 · 族长',title='开春了',body='族长把骨刀交到你手里：「往后记事，就靠你了。」',rot=3,dx=20,opt=('接过骨刀',.4))+'<div class="coach" style="left:868px;right:auto;width:320px;top:300px">左右拖卡做选择，或按 <span class="k">←</span> <span class="k">→</span> 再按 <span class="k">Enter</span>。</div>',dots=[0,8,0,0],tray=E3)
r3=col(d1,'<span style="color:#B5432E;font-weight:700">动效中间帧，越框是故意的</span><br><b>电脑 · 教学提示</b>：提示条放在卡右侧外（不压卡面），宽 320；带键位。',704)
page('教学开局','差距 #3（优先级 3）',f'<div class="h2"><b>6</b>前五张教学卡 + 第一代结束<span>差距 #3</span></div><div class="row">{r1}</div><div class="row" style="margin-top:24px">{r2}</div><div class="h2"><b>7</b>电脑端</div><div class="row">{r3}</div>','gf3_tutorial')
